"""Fresh source-authored body operands. This is a proposal, not binding authority.

Rows are entered from the selected source, never filled from a previous price.
Repeated syntax is represented by explicit source templates. Old JSON is used
by the separate generator for comparison and the protected old190 catalogue.
"""
ORDER=('R','W','C','X','LE','H','Z','O','A','F')
ROWS={}
def row(name,values,operations,helpers='',bare='',b=None,d=None,sponsors=''):
    a=[int(x) for x in values.split()]
    assert len(a)==10 and name not in ROWS,name
    co={}
    for term in helpers.split():
        key,_,n=term.partition(':');co[key]=int(n or '1')
    ROWS[name]=dict(body_vector=a,operations=operations,helper_coefficients=co,
        bare_own_identifiers=bare,body_B_vector=b or [0]*10,body_d_vector=d or [0]*10,
        sponsors=sponsors)

